from pathlib import Path
import json
HERE=Path(__file__).resolve().parent
UID={'type':'string','pattern':'^urn:uuid:[0-9a-f-]{36}$'}
ref=lambda s:{'$ref':'#/$defs/'+s}
fact={'type':'object','required':['state','value','binding'],'additionalProperties':False,'properties':{'state':{'enum':['known','unknown','not_stated','not_applicable','requires_runtime','verbatim_only','partially_structured']},'value':{},'binding':ref('binding')},'allOf':[{'if':{'properties':{'state':{'const':'known'}}},'then':{'properties':{'value':{'not':{'type':'null'}}}}}]}
binding={'type':'object','additionalProperties':False,'required':['source_evidence_id','source_entry_id','source_note_utf8_range','mapping_rule_id','adopted_decision_ids'],'properties':{'source_evidence_id':UID,'source_entry_id':UID,'mapping_rule_id':UID,'adopted_decision_ids':{'type':'array','items':UID},'source_note_utf8_range':{'type':'object','required':['start','end'],'additionalProperties':False,'properties':{'start':{'type':'integer','minimum':0},'end':{'type':'integer','minimum':1}}}}}
spellcontract={'type':'object','required':['base_level','activation','range','targeting','components','duration','concentration','save_attack','upcast','effects','coverage'],'additionalProperties':False,'properties':{k:ref('fact') for k in ['base_level','activation','range','targeting','duration','concentration','save_attack','upcast']}}
spellcontract['properties'].update(components={'type':'object','required':['verbal','somatic','material','material_detail','material_consumption','material_value'],'additionalProperties':False,'properties':{k:ref('fact') for k in ['verbal','somatic','material','material_detail','material_consumption','material_value']}},effects={'type':'array','minItems':1,'items':ref('fact')},coverage={'type':'string','minLength':1})
callkeys=['spell_id','mode','mapping_adoption_ids','cast_level','parameter_owner','casting_ability','save_dc','spell_attack_bonus','components_waived','concentration_override','target_override','availability','uncompiled_qualifications']
call={'type':'object','required':callkeys,'additionalProperties':False,'properties':{k:ref('fact') for k in callkeys if k not in ['spell_id','mode','mapping_adoption_ids']}}
call['properties'].update(spell_id=UID,mode={'enum':['intrinsic_spell_call','stored_spell_instance']},mapping_adoption_ids={'type':'array','items':UID})
ability={'type':'object','required':['id','owner_id','title','verbatim_text','critical_fields','mechanics','extensions','source_evidence_id'],'properties':{'id':UID,'owner_id':UID,'source_evidence_id':UID,'title':{'type':'string','minLength':1},'verbatim_text':{'type':'string','minLength':1},'critical_fields':{'type':'object'},'mechanics':{'type':'object','required':['kind','clauses','dependencies']},'extensions':{'type':'object','required':['lorebuddy.dnd2024'],'properties':{'lorebuddy.dnd2024':{'type':'object','required':['source_parameter_bindings'],'properties':{'casting_calls':{'type':'array','minItems':1,'items':ref('call')}}}}}}}
card={'type':'object','required':['id','title','rule_context_id','verbatim_text','source_evidence_id','header','abilities','candidate_revision','extensions'],'properties':{'id':UID,'source_evidence_id':UID,'rule_context_id':UID,'verbatim_text':{'type':'string','minLength':1},'abilities':{'type':'array','minItems':1,'items':ref('ability')},'candidate_revision':{'type':'integer','minimum':1},'extensions':{'type':'object','required':['lorebuddy.dnd2024']}}}
spell={'type':'object','required':['id','alias','verbatim_text','source_evidence_id','extensions'],'properties':{'id':UID,'source_evidence_id':UID,'verbatim_text':{'type':'string','minLength':1},'extensions':{'type':'object','required':['lorebuddy.dnd2024'],'properties':{'lorebuddy.dnd2024':{'type':'object','required':['casting_contract'],'properties':{'casting_contract':ref('spellcontract')}}}}}}
root={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'urn:lorebuddy:research:dnd2024:production-contract:1','title':'Finite D&D2024 production contract v1; not platform Core','$defs':{'binding':binding,'fact':fact,'spellcontract':spellcontract,'call':call,'ability':ability,'card':card,'spell':spell},'type':'object','required':['delivery_id','format_revision','schema_revision','contract_id','contract_revision','cards','spells','shared_rules','expressions','relations','clusters','evidence','sources','mapping_rules','compatibility','delivery_policy'],'properties':{'delivery_id':UID,'format_revision':{'const':'lorebuddy.dnd2024.rule-cluster-contract-1'},'schema_revision':{'const':'1.0.0'},'contract_revision':{'const':'v1-r1'},'cards':{'type':'array','minItems':8,'maxItems':8,'items':ref('card')},'spells':{'type':'array','minItems':11,'maxItems':11,'items':ref('spell')},'shared_rules':{'type':'array','minItems':6,'maxItems':6},'clusters':{'type':'array','minItems':8,'maxItems':8},'delivery_policy':{'type':'object','properties':{'formal_rule_approval':{'const':False},'consumer_acceptance':{'const':'pending'}}}}}
question={'type':'object','required':['id','question','request_scope','scene','delivery'],'additionalProperties':False,'properties':{'id':{'type':'string','minLength':1},'question':{'type':'string','minLength':1},'request_scope':{'enum':['damage_and_linked','full_ability','hp_settlement','source_state_change','instance_migration']},'delivery':{'type':'string'},'scene':{'type':'object','required':['roster','event'],'additionalProperties':False,'properties':{'roster':{'type':'array','minItems':1,'items':{'type':'object','required':['instance_id','prototype_id'],'properties':{'instance_id':{'type':'string','minLength':1},'prototype_id':{'anyOf':[UID,{'type':'null'}]}}}},'event':{'type':'object','required':['actor_instance_id','declared_action_name','target_instance_ids','amount_mode'],'properties':{'actor_instance_id':{'type':'string'},'declared_action_name':{'type':'string'},'target_instance_ids':{'type':'array','minItems':1,'items':{'type':'string'}},'amount_mode':{'enum':['printed_fixed','recorded_roll']}}}}}}}
scene={'$schema':root['$schema'],'$id':'urn:lorebuddy:research:dnd2024:scene-request:1','title':'24-case scene/request exchange fixture; no bound calculator parameters','type':'object','required':['corpus_delivery_id','format_revision','instructions','questions'],'additionalProperties':False,'properties':{'corpus_delivery_id':UID,'format_revision':{'const':'lorebuddy.dnd2024.scene-request-1'},'instructions':{'type':'string'},'questions':{'type':'array','minItems':24,'maxItems':24,'items':question}}}
# Batch cardinality belongs to intake/audit, not the reusable exchange contract.
for key in ['cards','spells','shared_rules','clusters']:
 root['properties'][key]['minItems']=1
 root['properties'][key].pop('maxItems',None)
scene['title']='Finite D&D2024 scene/request exchange; batch cardinality is in the intake plan'
scene['properties']['questions']['minItems']=1
scene['properties']['questions'].pop('maxItems',None)
for name,schema in [('lorebuddy.dnd2024.production.json',root),('lorebuddy.dnd2024.scene-request.json',scene)]:
 (HERE/'schemas'/name).write_text(json.dumps(schema,ensure_ascii=False,indent=2)+'\n')
print('Two finite namespace schemas generated.')
